def render(config: dict) -> None:
    """Render the shared package, then add the public-protection profile to its README."""
    render_decision_gate(config)
    readme_path = Path(__file__).resolve().parents[1] / config["path"] / "README.md"
    text = readme_path.read_text()
    text = text.replace(
        '<a href="../../DECISION_GATE_CONTRACT.md">Decision Gate Contract</a> ·',
        '<a href="../../DECISION_GATE_CONTRACT.md">Decision Gate Contract</a> · <a href="../../PROTECTION_RECEIPT_CONTRACT.md">Protection Receipt Contract</a> ·',
    )
    text = text.replace(
        "This lab implements the repository's **Decision Gate Contract**. A run passes only when the\n",
        "This lab implements the repository's **Decision Gate Contract** and its **Protection Receipt\nContract** profile. A run passes only when the\n",
    )
    readme_path.write_text(text)


def main() -> None:
    for config in WAVE:
        render(config)
    print(f"generated {len(WAVE)} public-protection labs")


if __name__ == "__main__":
    main()
